import{_ as e,a0 as r,w as s,s as b,ao as i,I as n,x as u,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Ubuntu 裏的“間諜軟件”將在 Ubuntu 16.04 LTS 中被禁用 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 裏的“間諜軟件”將在 Ubuntu 16.04 LTS 中被禁用 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 裏的“間諜軟件”將在 Ubuntu 16.04 LTS 中被禁用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 裏的“間諜軟件”將在 Ubuntu 16.04 LTS 中被禁用 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20160111 Ubuntu-‘Spyware’-Will-Be-Disabled-In-Ubuntu-16.04-LTS","title":"Ubuntu 裏的“間諜軟件”將在 Ubuntu 16.04 LTS 中被禁用","tag":"201601","desc":""},"relativePath":"201601/20160111 Ubuntu-‘Spyware’-Will-Be-Disabled-In-Ubuntu-16.04-LTS.md","filePath":"[post].md"}'),p={name:"201601/20160111 Ubuntu-‘Spyware’-Will-Be-Disabled-In-Ubuntu-16.04-LTS.md"};function d(m,t,g,U,f,T){const l=r("Link");return s(),b("div",null,[t[30]||(t[30]=i('<h1 id="ubuntu-裏的-間諜軟件-將在-ubuntu-16-04-lts-中被禁用" tabindex="-1">Ubuntu 裏的“間諜軟件”將在 Ubuntu 16.04 LTS 中被禁用 <a class="header-anchor" href="#ubuntu-裏的-間諜軟件-將在-ubuntu-16-04-lts-中被禁用" aria-label="Permalink to “Ubuntu 裏的“間諜軟件”將在 Ubuntu 16.04 LTS 中被禁用”">​</a></h1><p>出於用户隱私的考慮，Ubuntu 閹割了一個有爭議的功能。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/09/as2.jpg" alt=""></p><p><strong>Unity 中有爭議的在線搜索功能將在今年四月份發佈的 Ubuntu 16.04 LTS 中被默認禁用</strong></p><p>用户在 Unity 7 的 Dash 搜索欄裏將<strong>只能搜索到本地文件、文件夾以及應用</strong>。這樣，用户輸入的關鍵詞將不會被髮送到 Canonical 或任何第三方內容提供商的服務器裏。</p><blockquote><p>“現在，Unity 的在線搜索在默認狀況下是關閉的”</p></blockquote><p>在目前 ubuntu 的支持版本中，Dash 欄會將用户搜索的關鍵詞發送到 Canonical 運營的遠程服務器中。它發送這些數據以用於從50多家在線服務獲取搜索結果，這些服務包括維基百科、YouTube 和 The Weather Channel 等。</p><p>我們可以選擇去<strong>系統設置 &gt; 隱私控制</strong>關閉這項功能。但是，一些開源社區針對的是默認打開這個事情。</p><h3 id="ubuntu-在線搜索引發的爭議" tabindex="-1">Ubuntu 在線搜索引發的爭議 <a class="header-anchor" href="#ubuntu-在線搜索引發的爭議" aria-label="Permalink to “Ubuntu 在線搜索引發的爭議”">​</a></h3><blockquote><p>“Richard Stallman 將這個功能描述為 ‘間諜軟件’”</p></blockquote><p>早在2012年，在 Ubuntu 搜索中整合了來自亞馬遜的內容之後，開源社區就表示為其用户的隱私感到擔憂。在2013年，“Smart Scopes 服務”全面推出後，開源社區再度表示擔憂.</p>',11)),n("p",null,[t[1]||(t[1]=u("風波如此之大，以至於開源界大神 ",-1)),o(l,{href:"http://arstechnica.com/information-technology/2012/12/richard-stallman-calls-ubuntu-spyware-because-it-tracks-searches/?utm_source=omgubuntu"},{default:a(()=>[...t[0]||(t[0]=[u('Richard Stallman 都稱 Ubuntu 為"間諜軟件"',-1)])]),_:1}),t[2]||(t[2]=u("。",-1))]),n("p",null,[o(l,{href:"https://www.eff.org/deeplinks/2012/10/privacy-ubuntu-1210-amazon-ads-and-data-leaks?utm_source=omgubuntu"},{default:a(()=>[...t[3]||(t[3]=[u("電子前哨基金會 (EFF)",-1)])]),_:1}),t[5]||(t[5]=u("也在一系列博文中表達出對此的關注，並且建議 Canonical 將這個功能做成用户自由選擇是否開啓的功能。Privacy International 比其他的組織走的更遠，對於 Ubuntu 的工作，他們給 Ubuntu 的締造者發了一個“",-1)),o(l,{href:"http://www.omgubuntu.co.uk/2013/10/ubuntu-wins-big-brother-austria-privacy-award"},{default:a(()=>[...t[4]||(t[4]=[u("老大哥獎",-1)])]),_:1}),t[6]||(t[6]=u("”。",-1))]),n("p",null,[o(l,{href:"http://blog.canonical.com/2012/12/07/searching-in-the-dash-in-ubuntu-13-04/"},{default:a(()=>[...t[7]||(t[7]=[u("Canonical",-1)])]),_:1}),t[8]||(t[8]=u(" 堅稱 Unity 的在線搜索功能所收集的數據是匿名的以及“不可識別是來自哪個用户的”。",-1))]),n("p",null,[t[10]||(t[10]=u("在",-1)),o(l,{href:"http://blog.canonical.com/2012/12/07/searching-in-the-dash-in-ubuntu-13-04/?utm_source=omgubuntu"},{default:a(()=>[...t[9]||(t[9]=[u("2013年 Canoical 發佈的博文中",-1)])]),_:1}),t[11]||(t[11]=u("他們解釋道：“",-1)),t[12]||(t[12]=n("strong",null,"(我們)會使用户瞭解我們收集哪些信息以及哪些第三方服務商將會在他們搜索時從 Dash 欄中給出結果。我們只會收集能夠提升用户體驗的信息。",-1)),t[13]||(t[13]=u("”",-1))]),t[31]||(t[31]=n("h3",{id:"ubuntu-開始嚴肅對待的用户數據隱私",tabindex:"-1"},[u("Ubuntu 開始嚴肅對待的用户數據隱私### "),n("a",{class:"header-anchor",href:"#ubuntu-開始嚴肅對待的用户數據隱私","aria-label":"Permalink to “Ubuntu 開始嚴肅對待的用户數據隱私###”"},"​")],-1)),t[32]||(t[32]=n("p",null,"Canonical 在給新安裝的 Ubuntu 14.04 LTS 以及以上版本中禁用了來自亞馬遜的產品搜索結果（儘管來自其他服務商的搜索結果仍然在出現，直到你關閉這個選項）",-1)),t[33]||(t[33]=n("p",null,"在下一個LTS（長期支持）版，也就是 Ubuntu 16.04 中，Canonical 完全關閉了這個有爭議的在線搜索功能，這個功能在用户安裝完後就是關閉的。就如同 EFF 在2012年建議他們做的那樣。",-1)),n("p",null,[t[15]||(t[15]=u("“你搜索的關鍵詞將不會逃出你的計算機。” ",-1)),o(l,{href:"http://www.whizzy.org/2015/12/online-searches-in-the-dash-to-be-off-by-default?utm_source=omgubuntu"},{default:a(()=>[...t[14]||(t[14]=[u("Ubuntu 桌面主管 Will Cooke",-1)])]),_:1}),t[16]||(t[16]=u("解釋道，“對於搜索結果的更精細的控制”和 Unity 8 所提供的“更有針對性的結果添加不到 Unity 7 裏”。",-1))]),t[34]||(t[34]=i('<p>這也就是“[Unity 7]的在線搜索功能將會退役”的原因。</p><p>這個變化也會降低對 Unity 7 的支持以及對 Canonical 基礎設施的壓力。Unity 提供的搜索結果越少，Canonical 就能把時間和工程師放到更加振奮人心的地方，比如更早的發佈 Unity 8 桌面環境。</p><h3 id="在-ubuntu-16-04-中你需要自己開啓在線搜索功能" tabindex="-1">在 Ubuntu 16.04 中你需要自己開啓在線搜索功能 <a class="header-anchor" href="#在-ubuntu-16-04-中你需要自己開啓在線搜索功能" aria-label="Permalink to “在 Ubuntu 16.04 中你需要自己開啓在線搜索功能”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/04/privacy.jpg" alt="Privacy settings in Ubuntu let you opt in to seeing online results"></p><p><em>在 Ubuntu 隱私設置中你可以打開在線搜索功能</em></p><p>禁用 Ubuntu 桌面的在線搜索功能的決定將獲得眾多開源/免費軟件社區的歡呼。但是並不是每一個人都對 Dash 提供的語義搜索功能反感，如果你認為你失去了在搜索時預覽天氣、查看新聞或其他來自 Dash 在線搜索提供的內容所帶來的效率的話，你只需要簡單的點幾下鼠標就可以<strong>再次打開這個功能</strong>，定位到 Ubuntu 的<strong>系統設置 &gt; 隱私控制 &gt; 搜索</strong>然後將選項調至“<strong>開啓</strong>”。</p><p>這個選項不會自動把亞馬遜的產品信息加入到搜索結果中。如果你想看產品信息的話，需要打開第二個可選項“shipping lens”才能看到來自 Amazon （和 Skimlinks）的內容。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><ul><li>默認情況下，Ubuntu 16.04 LTS 的 Dash 欄將不會搜索到在線結果</li><li>可以手動打開在線搜索</li><li><strong>系統設置 &gt; 隱私控制 &gt; 搜索</strong>中的第二個可選項允許你看到亞馬遜的產品信息</li><li>這個變動只會影響新安裝的系統。從老版本升級的將會保留用户的喜好</li></ul><p>你同意這個決定嗎？抑或是 Cononical 可能降低了新用户的體驗？在評論中告訴我們。</p><hr>',11)),n("p",null,[t[18]||(t[18]=u("via: ",-1)),o(l,{href:"http://www.omgubuntu.co.uk/2016/01/ubuntu-online-search-feature-disabled-16-04"},{default:a(()=>[...t[17]||(t[17]=[u("http://www.omgubuntu.co.uk/2016/01/ubuntu-online-search-feature-disabled-16-04",-1)])]),_:1})]),n("p",null,[t[22]||(t[22]=u("作者：",-1)),o(l,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:a(()=>[...t[19]||(t[19]=[u("Joey-Elijah Sneddon",-1)])]),_:1}),t[23]||(t[23]=u(" 譯者：",-1)),o(l,{href:"https://github.com/name1e5s"},{default:a(()=>[...t[20]||(t[20]=[u("name1e5s",-1)])]),_:1}),t[24]||(t[24]=u(" 校對：",-1)),o(l,{href:"https://github.com/wxy"},{default:a(()=>[...t[21]||(t[21]=[u("wxy",-1)])]),_:1})]),n("p",null,[t[27]||(t[27]=u("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[25]||(t[25]=[u("LCTT",-1)])]),_:1}),t[28]||(t[28]=u(" 原創編譯，",-1)),o(l,{href:"https://linux.cn/"},{default:a(()=>[...t[26]||(t[26]=[u("Linux中國",-1)])]),_:1}),t[29]||(t[29]=u(" 榮譽推出",-1))])])}const y=e(p,[["render",d]]);export{C as __pageData,y as default};
